.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl {
  display: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl:after,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl:before,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl *,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl *:after,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl *:before,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl + .tgl-btn {
  box-sizing: border-box;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl:after::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl:before::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl *::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl *:after::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl *:before::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl + .tgl-btn::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl:after::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl:before::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl *::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl *:after::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl *:before::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl + .tgl-btn::selection {
  background: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl + .tgl-btn {
  outline: 0;
  display: block;
  width: 4em;
  height: 2em;
  position: relative;
  cursor: pointer;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl + .tgl-btn:after,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl + .tgl-btn:before {
  position: relative;
  display: block;
  content: "";
  width: 50%;
  height: 100%;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl + .tgl-btn:after {
  left: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl + .tgl-btn:before {
  display: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl:checked + .tgl-btn:after {
  left: 50%;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed + .tgl-btn {
  overflow: hidden;
  transform: skew(-10deg);
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  transition: all 0.2s ease;
  font-family: sans-serif;
  background: #888;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed + .tgl-btn:after,
  .__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed + .tgl-btn:before {
  transform: skew(10deg);
  display: inline-block;
  transition: all 0.2s ease;
  width: 100%;
  text-align: center;
  position: absolute;
  line-height: 2em;
  font-weight: bold;
  color: #fff;
  text-shadow: 0 1px 0 rgba(0, 0, 0, 0.4);
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed + .tgl-btn:after {
  left: 100%;
  content: attr(data-tg-on);
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed + .tgl-btn:before {
  left: 0;
  content: attr(data-tg-off);
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed + .tgl-btn:active {
  background: #888;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed + .tgl-btn:active:before {
  left: -10%;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed:checked + .tgl-btn {
  background: #86d993;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed:checked + .tgl-btn:before {
  left: -100%;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed:checked + .tgl-btn:after {
  left: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper-8 .tgl-skewed:checked + .tgl-btn:active:after {
  left: 10%;
}
